Question 5
Compare run time between parLapply, foreach and replicate for the above problem.

cl5 &lt;- makeCluster(3)
registerDoParallel(cl5)

time_par1 &lt;- system.time({
  lval_par &lt;- parLapply(cl5,1:3,function(i) {max(rnorm(5))})
})
time_par2 &lt;- system.time({
  lval_par &lt;- parLapply(cl5,1:10000,function(i) {max(rnorm(5))})
})

time_for1 &lt;- system.time({
  lval_for &lt;- foreach(i = irnorm(5,count = 3), .combine = c) %dopar% {max(i)}
})
time_for2 &lt;- system.time({
  lval_for &lt;- foreach(i = irnorm(5,count = 10000), .combine = c) %dopar% {max(i)}
})

time_rep1 &lt;- system.time({
  lval_rep &lt;- replicate(3,max(rnorm(5)))
})
time_rep2 &lt;- system.time({
  lval_rep &lt;- replicate(10000,max(rnorm(5)))
})

stopCluster(cl5)

results &lt;- data.frame(
  Method = c("parLapply","foreach","replicate"),
  `Time (3 vectors)` = c(time_par1[3],time_for1[3],time_rep1[3]),
  `Time (10000 vectors)` = c(time_par2[3],time_for2[3],time_rep2[3]),
  check.names = FALSE
)
kable(results)




